// Coin.cs
using UnityEngine;

public class Coin : MonoBehaviour
{
    public static int score = 0;

    void OnTriggerEnter(Collider other)
    {
        if (other.CompareTag("Player"))
        {
            score++;
            Debug.Log("Score: " + score);
            Destroy(gameObject);
        }
    }
}

